mapper.select:
SELECT a.id,a.username,a.cell_phone,a.state,a.domain,a.sex,u.power_id,p.power_name FROM account a,USER u,POWER p WHERE a.id = u.account_id AND u.power_id = p.power_id AND p.power_id != 1001
AND a.username LIKE "%"#{username}"%"
LIMIT #{page},#{rows};

mapper.update:
UPDATE
    account
SET
    state = #{state}
WHERE
    id = #{accountId};
